import assert from "node:assert/strict";
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { test } from "node:test";

import { createStorageWriteAuthority, assertStorageWriteAllowed } from "../../shared/retention/index.mjs";
import { DockerNoEgressSandboxBackend } from "../../extensions/evaluation-runner-local/no-egress-sandbox.mjs";

/**
 * Run 115 S24a (R32 first slice): closed private domains + bounded child scope.
 *
 * Row 1: the retention write authority as an explicit factory boundary (it used to be a
 * module-global registry plus a free function). Rows 2-3: the private child scope that spawns the
 * docker CLI - what the current code actually guarantees on timeout and on a partially failed
 * startup: the child is killed by the timer and the container is released either way.
 *
 * Temp roots use the platform temp directory (this suite runs on Windows and Linux CI).
 */

const TEMP_ROOT = (await import("node:os")).tmpdir();
async function tempRoot(label) {
  return mkdtemp(path.join(TEMP_ROOT, "run115-s24a-" + label + "-"));
}
const image = "node@sha256:" + "a".repeat(64);

const FAKE_DOCKER = [
  'import { appendFileSync } from "node:fs";',
  "const argv = process.argv.slice(2);",
  'const ledger = argv[argv.indexOf("--ledger") + 1];',
  'const mode = argv[argv.indexOf("--mode") + 1];',
  "const rest = argv.slice(4);",
  "const command = rest[0];",
  'const record = (line) => { try { appendFileSync(ledger, line + "\\n"); } catch {} };',
  'if (command === "run") {',
  '  record("run");',
  '  if (mode === "hang") setInterval(() => {}, 1000);',
  '  else { process.stdout.write("fake-container-id\\n"); process.exit(mode === "exit3" ? 3 : 0); }',
  '} else if (command === "rm") {',
  '  record("rm " + rest.join(" "));',
  "  process.exit(0);",
  '} else if (command === "cp") {',
  '  record("cp");',
  '  process.exit(mode === "cpfail" ? 1 : 0);',
  "} else {",
  "  process.exit(0);",
  "}",
].join("\n");

async function sandboxHarness(label, mode) {
  const root = await tempRoot(label);
  const workspaceRoot = path.join(root, "workspace");
  const cwd = path.join(workspaceRoot, "run");
  await mkdir(cwd, { recursive: true });
  const fakeScript = path.join(root, "fake-docker.mjs");
  const ledger = path.join(root, "ledger.txt");
  await writeFile(fakeScript, FAKE_DOCKER);
  const backend = new DockerNoEgressSandboxBackend({
    image,
    workspaceRoot,
    tempRoot: path.join(root, "sandbox-tmp"),
    dockerExecutable: process.execPath,
    dockerExecutableArgs: [fakeScript, "--ledger", ledger, "--mode", mode],
    timeoutMs: 10_000,
  });
  const input = {
    networkPolicy: "deny_all", killProcessTree: true, executable: "node", args: ["-e", "0"], cwd,
    // Run 115 lead fix: 400 ms was load-flaky under parallel file execution - the child could not
    // spawn and append its ledger line before the timer fired. The semantics under test (a child
    // that never becomes ready is killed and released) do not depend on the deadline being short.
    timeoutMs: 2_000, maxStdoutBytes: 1024, maxStderrBytes: 1024,
    maxFiles: 8, maxFileBytes: 1024, maxWorkspaceBytes: 8192,
  };
  const readLedger = async () => (await readFile(ledger, "utf8").catch(() => "")).split("\n").filter(Boolean);
  return { root, backend, input, readLedger };
}

test("R32: the retention write authority is a factory with an explicit registry dependency", () => {
  assert.throws(() => createStorageWriteAuthority(), /explicit non-empty storage registry/);
  assert.throws(() => createStorageWriteAuthority({ registry: {} }), /explicit non-empty storage registry/);
  assert.throws(() => createStorageWriteAuthority({ registry: new Map() }), /explicit non-empty storage registry/);

  const registry = new Map([["scoped_store", { id: "scoped_store", channels: ["stage"] }]]);
  const authority = createStorageWriteAuthority({ registry });
  assert.equal(authority.authority, "storage-write-registry");
  assert.equal(authority.assertAllowed("scoped_store", "stage").id, "scoped_store");
  assert.throws(() => authority.assertAllowed("scoped_store", "development"), /not writable in development/);
  assert.throws(() => authority.assertAllowed("event_log", "development"), /unregistered storage class/);
  // The authority reads the injected registry live rather than snapshotting it.
  registry.set("late_store", { id: "late_store", channels: ["stage"] });
  assert.equal(authority.assertAllowed("late_store", "stage").id, "late_store");

  // The module-level free function keeps the previous behaviour through the module authority.
  assert.equal(assertStorageWriteAllowed("event_log", "development").id, "event_log");
  assert.throws(() => assertStorageWriteAllowed("event_log", "unknown-channel"), /not writable in unknown-channel/);
  assert.throws(() => assertStorageWriteAllowed("not_a_store", "development"), /unregistered storage class/);
});

test("R32: a sandbox child that never becomes ready is killed by the timeout and its container is released", async () => {
  const harness = await sandboxHarness("timeout", "hang");
  try {
    const receipt = await harness.backend.run(harness.input);
    const ledger = await harness.readLedger();
    assert.ok(ledger.includes("run"), "the child must have been spawned");
    assert.equal(receipt.timedOut, true, "the timer must stop the child");
    assert.ok(ledger.some((line) => line.startsWith("rm ")), "a timed-out sandbox must still release its container");
    assert.equal(receipt.receipt.cleanup, "removed");
  } finally {
    await rm(harness.root, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
  }
});

test("R32: a partially failed startup (container exited or output inspection failed) still releases the child", async () => {
  const failing = await sandboxHarness("partial", "cpfail");
  try {
    await assert.rejects(failing.backend.run(failing.input), /writable output inspection failed/);
    const ledger = await failing.readLedger();
    assert.ok(ledger.includes("run"));
    assert.ok(ledger.some((line) => line.startsWith("rm ")), "a failed startup must still release its container");
  } finally {
    await rm(failing.root, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
  }

  const exited = await sandboxHarness("exit", "exit3");
  try {
    const receipt = await exited.backend.run(exited.input);
    assert.equal(receipt.exitCode, 3, "a container that exits nonzero is reported, not hidden");
    assert.ok((await exited.readLedger()).some((line) => line.startsWith("rm ")), "an exited container must still be released");
  } finally {
    await rm(exited.root, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
  }
});

